"""Tests of openspacehdl new and update (openspacehdl.project), the generated files and add_system."""

import copy
import hashlib
import json
import re
import shutil
from pathlib import Path

import pytest

from openspacehdl import cli, composer, lock, project, vunit
from openspacehdl.installed import Installed

FIX = Path(__file__).resolve().parent / "fixtures" / "composer"
SCHEMAS = FIX / "schema"
EXAMPLE = FIX / "spw_rmap_node" / "spw_rmap_node.composer.json"
DATA = json.loads(EXAMPLE.read_text(encoding="utf-8"))
E = "spw_rmap_node"
GENERATED = [f"sim/tb/{E}_th.vhd", f"sim/tb/{E}_th_pkg.vhd"]
SEEDS = ["README.md", "sim/run.py", f"sim/tb/{E}_tb.vhd"]


def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def make_lock(files=None):
    """A lock manifest with the pins of the example."""
    cores, olo = [], None
    for c in DATA["resolved"]["compile"]:
        if c["library"] == "olo":
            olo = c
        elif c["library"] != E:
            cores.append({"id": c["library"], "name": c["library"].title(),
                          "repository": f"open-space-hdl/{c['source']}",
                          "tag": "v0.1.0", "commit": c["commit"], "library": c["library"],
                          "fileList": "compile_order.txt", "fileListFormat": "files", "models": {}})
    return lock.Lock.from_dict({
        "format": "openspacehdl-lock", "version": 1, "package": "0.1.0",
        "website": {"commit": "7" * 40, "catalog": "x", "generator": "0.9.8-beta"},
        "referenceSystems": {"tag": "v0.1.1", "commit": "4" * 40},
        "openLogic": {"tag": olo["tag"], "commit": olo["commit"], "library": "olo", "fileList": "compile_order.txt",
                      "repository": "open-space-hdl/open-logic-ft"},
        "uvvm": {"commit": "5" * 40}, "cores": cores, "files": files or {},
    })


LOCK = make_lock()


def new(dest, source=EXAMPLE, **kw):
    return project.new(source, dest, lock=LOCK, schema_dir=SCHEMAS, **kw)


def update(dest, **kw):
    return project.update(dest, lock=LOCK, schema_dir=SCHEMAS, **kw)


def variant(tmp_path, mutate):
    """A changed copy of the example with an export whose header names its SHA-256."""
    data = copy.deepcopy(DATA)
    mutate(data)
    d = tmp_path / "variant"
    d.mkdir()
    target = d / f"{E}.composer.json"
    target.write_text(json.dumps(data, indent=1), encoding="utf-8")
    shutil.copytree(EXAMPLE.parent / "hdl", d / "hdl")
    order = d / "hdl" / f"{E}_compile_order.txt"
    digest = sha(target)
    order.write_text(re.sub(r"(# SHA-256 of .*: )[0-9a-f]{64}", lambda m: m.group(1) + digest,
                            order.read_text(encoding="utf-8")), encoding="utf-8", newline="\n")
    return target


@pytest.fixture
def proj(tmp_path):
    dest = tmp_path / "proj"
    new(dest)
    return dest


def test_new_writes_the_project(proj):
    files = sorted(p.relative_to(proj).as_posix() for p in proj.rglob("*") if p.is_file())
    hdl = sorted(f"hdl/{f.name}" for f in (EXAMPLE.parent / "hdl").iterdir())
    assert files == sorted([f"{E}.composer.json", *hdl, *GENERATED, *SEEDS, ".openspacehdl/project.json"])
    assert (proj / f"{E}.composer.json").read_bytes() == EXAMPLE.read_bytes()
    m = json.loads((proj / ".openspacehdl/project.json").read_text(encoding="utf-8"))
    assert m["format"] == "openspacehdl-project" and m["system"] == E and m["composer"] == f"{E}.composer.json"
    assert m["lock"] == {"website": "7" * 40, "referenceSystems": "v0.1.1", "openLogic": LOCK.olo_tag}
    assert sorted(m["generated"]) == GENERATED and m["seeds"] == sorted(SEEDS)
    assert all(m["generated"][p] == sha(proj / p) for p in GENERATED)
    assert all(m["inputs"][p] == sha(proj / p) for p in m["inputs"])


def test_headers(proj):
    gen = (proj / GENERATED[0]).read_text(encoding="utf-8").splitlines()
    assert gen[0].startswith("-- Generated by openspacehdl ") and gen[0].endswith(f"from {E}.composer.json")
    assert gen[1] == "-- Lock: website 7777777777, reference-systems v0.1.1"
    assert gen[2] == "-- Class: generated. Regenerated by openspacehdl update; edits are kept and reported."
    assert "-- Copyright (c) 2026 Julian Schneider" in gen and any("Permission is hereby granted" in g for g in gen)
    tb = (proj / f"sim/tb/{E}_tb.vhd").read_text(encoding="utf-8")
    assert "-- Class: seed. Written once by openspacehdl new; openspacehdl update never changes it." in tb
    assert "Permission is hereby granted" not in tb and "Copyright" not in tb
    run = (proj / "sim/run.py").read_text(encoding="utf-8")
    assert run.startswith("# Written by openspacehdl") and "osh.add_system(vu, PROJECT)" in run
    assert "osh.guard_ghdl_generics()" in run
    readme = (proj / "README.md").read_text(encoding="utf-8")
    assert readme.startswith("<!--\nWritten by openspacehdl") and "Class: seed." in readme
    for p in [*GENERATED, *SEEDS]:
        assert all(len(line) <= 120 for line in (proj / p).read_text(encoding="utf-8").splitlines()), p


def test_the_harness(proj):
    pkg = (proj / f"sim/tb/{E}_th_pkg.vhd").read_text(encoding="utf-8")
    assert "constant C_CLK_SYS_HZ     : positive := 100000000;" in pkg
    assert "constant C_CLK_LINK_HZ     : positive := 200000000;" in pkg
    assert "constant C_CLK_SYS_PERIOD : time     := 1 sec / C_CLK_SYS_HZ;" in pkg
    assert "constant C_SLOWEST_PERIOD : time     := C_CLK_SYS_PERIOD;" in pkg
    assert "signal osh_rst : std_logic := '1';" in pkg
    th = (proj / f"sim/tb/{E}_th.vhd").read_text(encoding="utf-8")
    ports = DATA["resolved"]["ports"]
    for p in ports:
        assert re.search(rf"^    signal {re.escape(p['name'])} +: ", th, re.M), p["name"]
        assert re.search(rf"^            {re.escape(p['name'])} +=> {re.escape(p['name'])},?$", th, re.M), p["name"]
    assert f"i_system : entity work.{E}" in th and "    Rst <= osh_rst;" in th
    assert "    Clk_sys <= not Clk_sys after C_CLK_SYS_PERIOD / 2;" in th
    assert re.search(r"signal spw_reg_S_AxiLite_AwAddr +: std_logic_vector\(7 downto 0\) := \(others => '0'\);", th)
    assert re.search(r"signal spw_reg_S_AxiLite_AwReady +: std_logic;$", th, re.M)


def test_new_refuses_a_directory_with_content(tmp_path):
    (tmp_path / "x.txt").write_text("mine", encoding="utf-8")
    with pytest.raises(project.ProjectError, match="not empty"):
        new(tmp_path)


def test_new_refuses_a_refused_system(tmp_path):
    with pytest.raises(composer.ComposerError, match="schema system-1"):
        new(tmp_path / "p", source=variant(tmp_path, lambda d: d["system"].pop("name")))


def test_update_right_after_new_changes_nothing(proj):
    before = {p: sha(p) for p in proj.rglob("*") if p.is_file()}
    r = update(proj)
    assert r.ok and r.written == [] and sorted(r.unchanged) == GENERATED
    assert {p: sha(p) for p in proj.rglob("*") if p.is_file()} == before


def test_update_from_a_changed_system(proj, tmp_path):
    source = variant(tmp_path, lambda d: next(c for c in d["resolved"]["clocks"] if c["name"].lower().startswith(
        "system")).update(frequencyHz=125000000))
    readme = sha(proj / "README.md")
    r = update(proj, source=source)
    assert r.ok and r.written == [f"sim/tb/{E}_th_pkg.vhd"] and r.unchanged == [f"sim/tb/{E}_th.vhd"]
    assert "C_CLK_SYS_HZ     : positive := 125000000;" in (proj / f"sim/tb/{E}_th_pkg.vhd").read_text(encoding="utf-8")
    assert (proj / f"{E}.composer.json").read_bytes() == source.read_bytes()
    assert sha(proj / "README.md") == readme
    assert update(proj).written == []


def test_an_edited_generated_file_is_kept(proj, tmp_path, capsys, cli_env):
    th = proj / f"sim/tb/{E}_th.vhd"
    th.write_text(th.read_text(encoding="utf-8") + "-- my change\n", encoding="utf-8")
    source = variant(tmp_path, lambda d: d["system"].update(description="changed"))
    r = update(proj, source=source)
    assert not r.ok and r.edited == [f"sim/tb/{E}_th.vhd"]
    assert th.read_text(encoding="utf-8").endswith("-- my change\n")
    assert (proj / f"sim/tb/{E}_th.vhd.new").is_file()
    assert update(proj).edited == [f"sim/tb/{E}_th.vhd"]
    monkey_cli(capsys, proj, 1, "edited, kept; the new text is in <file>.new: sim/tb/spw_rmap_node_th.vhd")


def test_a_deleted_generated_file(proj):
    (proj / f"sim/tb/{E}_th.vhd").unlink()
    r = update(proj)
    assert r.ok and r.deleted == [f"sim/tb/{E}_th.vhd"] and not (proj / f"sim/tb/{E}_th.vhd").exists()
    r = update(proj, restore=True)
    assert r.restored == [f"sim/tb/{E}_th.vhd"] and (proj / f"sim/tb/{E}_th.vhd").is_file()
    assert update(proj).unchanged == GENERATED


def test_a_file_of_the_integrator_where_a_generated_file_belongs(proj):
    m_file = proj / ".openspacehdl/project.json"
    m = json.loads(m_file.read_text(encoding="utf-8"))
    del m["generated"][f"sim/tb/{E}_th.vhd"]
    m_file.write_text(json.dumps(m), encoding="utf-8")
    (proj / f"sim/tb/{E}_th.vhd").write_text("-- mine\n", encoding="utf-8")
    r = update(proj)
    assert r.edited == [f"sim/tb/{E}_th.vhd"]
    assert (proj / f"sim/tb/{E}_th.vhd").read_text(encoding="utf-8") == "-- mine\n"


@pytest.mark.parametrize("changed", [False, True])
def test_a_file_no_longer_generated(proj, changed):
    old = proj / "sim/tb/old.vhd"
    old.write_text("-- old\n", encoding="utf-8")
    m_file = proj / ".openspacehdl/project.json"
    m = json.loads(m_file.read_text(encoding="utf-8"))
    m["generated"]["sim/tb/old.vhd"] = sha(old)
    m_file.write_text(json.dumps(m), encoding="utf-8")
    if changed:
        old.write_text("-- old, changed\n", encoding="utf-8")
    r = update(proj)
    if changed:
        assert not r.ok and r.kept_obsolete == ["sim/tb/old.vhd"] and old.is_file()
    else:
        assert r.ok and r.removed == ["sim/tb/old.vhd"] and not old.exists()


def test_dry_run_changes_nothing(proj, tmp_path):
    source = variant(tmp_path, lambda d: next(c for c in d["resolved"]["clocks"] if c["name"].lower().startswith(
        "system")).update(frequencyHz=125000000))
    before = {p: sha(p) for p in proj.rglob("*") if p.is_file()}
    r = update(proj, source=source, dry_run=True)
    assert r.written == [f"sim/tb/{E}_th_pkg.vhd"]
    assert {p: sha(p) for p in proj.rglob("*") if p.is_file()} == before


def test_update_refuses_another_system(proj, tmp_path):
    data = copy.deepcopy(DATA)
    data["resolved"]["entity"] = "other"
    d = tmp_path / "other"
    (d / "hdl").mkdir(parents=True)
    target = d / "other.composer.json"
    target.write_text(json.dumps(data, indent=1), encoding="utf-8")
    for f in (EXAMPLE.parent / "hdl").iterdir():
        text = f.read_text(encoding="utf-8")
        if f.name.endswith("_compile_order.txt"):
            text = re.sub(r"(# SHA-256 of .*: )[0-9a-f]{64}", lambda m: m.group(1) + sha(target), text)
        (d / "hdl" / f.name.replace(E, "other")).write_text(text, encoding="utf-8", newline="\n")
    with pytest.raises(project.ProjectError, match="is the system other, the project is spw_rmap_node"):
        update(proj, source=target)
    assert (proj / f"{E}.composer.json").read_bytes() == EXAMPLE.read_bytes()


def test_taking_over_the_new_text_makes_the_file_unchanged(proj, tmp_path):
    th = proj / f"sim/tb/{E}_th.vhd"
    before = th.read_text(encoding="utf-8")
    th.write_text(before + "-- my change\n", encoding="utf-8")

    def rename_port(d):
        d["resolved"]["ports"][-1]["name"] += "_renamed"

    assert update(proj, source=variant(tmp_path, rename_port)).edited == [f"sim/tb/{E}_th.vhd"]
    new_text = (proj / f"sim/tb/{E}_th.vhd.new").read_text(encoding="utf-8")
    assert new_text != before and "_renamed" in new_text
    shutil.move(str(th) + ".new", th)
    r = update(proj)
    assert r.ok and r.edited == [] and f"sim/tb/{E}_th.vhd" in r.unchanged


def test_dry_run_does_not_restore(proj):
    (proj / f"sim/tb/{E}_th.vhd").unlink()
    r = update(proj, dry_run=True, restore=True)
    assert r.restored == [f"sim/tb/{E}_th.vhd"] and not (proj / f"sim/tb/{E}_th.vhd").exists()


def test_a_stale_export_file_is_removed(proj, tmp_path):
    stale = proj / "hdl" / f"{E}_old.txt"
    stale.write_text("old export\n", encoding="utf-8")
    m_file = proj / ".openspacehdl/project.json"
    m = json.loads(m_file.read_text(encoding="utf-8"))
    m["inputs"][f"hdl/{E}_old.txt"] = sha(stale)
    m_file.write_text(json.dumps(m), encoding="utf-8")
    update(proj, source=variant(tmp_path, lambda d: d["system"].update(description="changed")))
    assert not stale.exists()


def test_update_outside_a_project(tmp_path):
    with pytest.raises(project.ProjectError, match="not a project of openspacehdl"):
        update(tmp_path)


def monkey_cli(capsys, proj, rc, text):
    capsys.readouterr()
    assert project.main_update(str(proj), None, None, False, False) == rc
    assert text in capsys.readouterr().out


@pytest.fixture
def cli_env(monkeypatch):
    monkeypatch.setattr(lock, "load", lambda: LOCK)
    monkeypatch.setattr(composer, "schema", lambda v, d=None: json.loads((SCHEMAS / f"system-{v}.json").read_text(
        encoding="utf-8")))


def test_the_commands(cli_env, tmp_path, capsys):
    assert cli.main(["new", str(EXAMPLE), str(tmp_path / "p")]) == 0
    assert f"wrote the project of {E}" in capsys.readouterr().out
    assert cli.main(["update", str(tmp_path / "p")]) == 0
    assert "nothing to update" in capsys.readouterr().out
    assert cli.main(["new", str(EXAMPLE), str(tmp_path / "p")]) == 1
    assert "not empty" in capsys.readouterr().err


# add_system against a recording stand-in for the VUnit object and a fake installed snapshot

class Source:
    def __init__(self):
        self.options = []

    def add_compile_option(self, name, value):
        self.options.append((name, value))


class Lib:
    def __init__(self, name):
        self.name, self.files, self.sources = name, [], {}

    def add_source_file(self, file_name, vhdl_standard=None):
        self.files.append(file_name)
        self.sources[file_name] = Source()
        return self.sources[file_name]

    def add_compile_option(self, name, value):
        pass


class FakeVUnit:
    def __init__(self, *existing):
        self.libs = {n: Lib(n) for n in existing}

    def add_library(self, name, vhdl_standard=None):
        assert name not in self.libs
        self.libs[name] = Lib(name)
        return self.libs[name]

    def library(self, name):
        return self.libs[name]

    def get_libraries(self, pattern="*", allow_empty=False):
        return list(self.libs.values())


@pytest.fixture
def system_env(proj, tmp_path, monkeypatch):
    """The project and an installed snapshot with every file its compile order lists (plus a small UVVM)."""
    sources, files = vunit.read_compile_order(proj / "hdl" / f"{E}_compile_order.txt")
    repos = {"open-logic-ft": "olo", "openwire": "openwire", "openrmap": "openrmap"}
    hdl = tmp_path / "installed"
    snap: dict[str, dict[str, str]] = {}
    for lib, path in files:
        repo, _, rel = path.partition("/")
        if rel and repo in repos:
            f = hdl / repos[repo] / rel
            f.parent.mkdir(parents=True, exist_ok=True)
            f.write_text(f"-- {rel}\n", encoding="utf-8")
            snap.setdefault(repos[repo], {})[rel] = sha(f)
    order = hdl / "uvvm" / "uvvm_util" / "script" / "compile_order.txt"
    order.parent.mkdir(parents=True)
    order.write_text("# library uvvm_util\n../src/types_pkg.vhd\n", encoding="utf-8")
    (hdl / "uvvm" / "uvvm_util" / "src").mkdir(parents=True)
    (hdl / "uvvm" / "uvvm_util" / "src" / "types_pkg.vhd").write_text("-- types\n", encoding="utf-8")
    snap["uvvm"] = {"uvvm_util/script/compile_order.txt": sha(order),
                    "uvvm_util/src/types_pkg.vhd": sha(hdl / "uvvm/uvvm_util/src/types_pkg.vhd")}
    inst = Installed(make_lock(snap), hdl)
    monkeypatch.setattr(vunit, "installed", lambda: inst)
    # add_osh_tb has tests of its own (test_vunit.py); here it records the call and adds UVVM only
    calls = []
    monkeypatch.setattr(vunit, "add_osh_tb", lambda vu: calls.append(vu) or vunit.add_uvvm(vu))
    return {"proj": proj, "inst": inst, "files": files, "osh_tb": calls}


def test_add_system(system_env):
    vu = FakeVUnit()
    lib = vunit.add_system(vu, system_env["proj"])
    assert lib is vu.libs[E] and system_env["osh_tb"] == [vu]
    assert sorted(vu.libs) == sorted(["olo", "openwire", "openrmap", E, "uvvm_util"])
    olo = [lib_ for lib_, p in system_env["files"] if lib_ == "olo"]
    assert len(vu.libs["olo"].files) == len(olo)
    assert all(s.options == [("ghdl.a_flags", list(vunit.RELAXED_GHDL_FLAGS))] for s in vu.libs["olo"].sources.values())
    assert all(s.options == [] for s in vu.libs["openwire"].sources.values())
    names = [Path(f).name for f in vu.libs[E].files]
    assert names[0] == f"{E}.vhd" and sorted(names[1:]) == sorted([f"{E}_tb.vhd", f"{E}_th.vhd", f"{E}_th_pkg.vhd"])
    assert vu.libs[E].sources[vu.libs[E].files[0]].options == []


def test_add_system_with_a_foreign_open_logic(system_env):
    with pytest.raises(vunit.OpenLogicConflictError):
        vunit.add_system(FakeVUnit("olo"), system_env["proj"])


def test_add_system_with_another_pin(system_env, monkeypatch):
    inst = system_env["inst"]
    other = make_lock(inst.lock.files)
    object.__setattr__(other.cores[0], "commit", "a" * 40)
    monkeypatch.setattr(vunit, "installed", lambda: Installed(other, inst.hdl))
    with pytest.raises(vunit.OshError, match="export the system again"):
        vunit.add_system(FakeVUnit(), system_env["proj"])


def test_add_system_replaces_the_files_of_a_vendor_adapter(system_env, monkeypatch, tmp_path):
    proj, inst = system_env["proj"], system_env["inst"]
    order = proj / "hdl" / f"{E}_compile_order.txt"
    text = order.read_text(encoding="utf-8")
    text = text.replace(f"file {E} {E}.vhd", f"file openwire openwire/hdl/x_pa/src/x_pa.vhd\n"
                                               f"file openwire openwire/hdl/x_pa/src/x_pa_struct.vhd\nfile {E} {E}.vhd")
    order.write_text(text, encoding="utf-8")
    files = {k: dict(v) for k, v in inst.lock.files.items()}
    for rel, body in (("hdl/x_pa/compile_order_sim.txt", "hdl/x_pa/src/x_pa.vhd\nhdl/x_pa/sim/x_pa_model.vhd\n"),
                      ("hdl/x_pa/src/x_pa.vhd", "-- entity\n"), ("hdl/x_pa/sim/x_pa_model.vhd", "-- model\n")):
        f = inst.hdl / "openwire" / rel
        f.parent.mkdir(parents=True, exist_ok=True)
        f.write_text(body, encoding="utf-8")
        files["openwire"][rel] = sha(f)
    lk = make_lock(files)
    ow = next(c for c in lk.cores if c.id == "openwire")
    object.__setattr__(ow, "models", {"x_pa": "hdl/x_pa/compile_order_sim.txt"})
    monkeypatch.setattr(vunit, "installed", lambda: Installed(lk, inst.hdl))
    vu = FakeVUnit()
    vunit.add_system(vu, proj)
    tail = [Path(f).as_posix().split("/openwire/")[-1] for f in vu.libs["openwire"].files[-2:]]
    assert tail == ["hdl/x_pa/src/x_pa.vhd", "hdl/x_pa/sim/x_pa_model.vhd"]
    relaxed = [s.options for s in list(vu.libs["openwire"].sources.values())[-2:]]
    assert relaxed == [[("ghdl.a_flags", list(vunit.RELAXED_GHDL_FLAGS))]] * 2


def test_the_ghdl_guard():
    pytest.importorskip("vunit")
    from vunit.sim_if.ghdl import GHDLInterface

    original = GHDLInterface._get_command
    try:
        vunit.guard_ghdl_generics()
        guarded = GHDLInterface._get_command
        vunit.guard_ghdl_generics()
        assert GHDLInterface._get_command is guarded and guarded is not original
        assert getattr(guarded, "_openspacehdl_guard", False)
    finally:
        GHDLInterface._get_command = original
